import sys
import zipfile
import xml.etree.ElementTree as ET

MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
PKG_REL = "http://schemas.openxmlformats.org/package/2006/relationships"


def q(tag):
    return "{%s}%s" % (MAIN, tag)


def cell_value(cell, shared):
    t = cell.get("t")
    v = cell.find(q("v"))
    text = ""
    if t == "s" and v is not None:
        idx = int(v.text)
        text = shared[idx] if idx < len(shared) else ""
    elif t == "inlineStr":
        is_ = cell.find(q("is"))
        if is_ is not None:
            text = "".join(x.text or "" for x in is_.iter(q("t")))
    elif t == "str" or v is not None:
        text = v.text if v is not None else ""
    return text


path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
z = zipfile.ZipFile(path)

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall(q("si")):
        shared.append("".join(x.text or "" for x in si.iter(q("t"))))

# Map sheet names to target paths using workbook.xml + rels
wb = ET.fromstring(z.read("xl/workbook.xml"))
rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
rid_to_target = {}
for rel in rels_root:
    rid_to_target[rel.get("Id")] = rel.get("Target")
sheets = []
for sh in wb.find(q("sheets")):
    name = sh.get("name")
    rid = sh.get("{%s}id" % REL)
    target = rid_to_target.get(rid, "")
    if not target.startswith("xl/") and not target.startswith("/"):
        target = "xl/" + target
    sheets.append((name, target.lstrip("/")))

for name, target in sheets:
    root = ET.fromstring(z.read(target))
    print("=== Sheet: %s ===" % name)
    for row in root.iter(q("row")):
        cells = {}
        for c in row.findall(q("c")):
            cells[c.get("r")] = cell_value(c, shared)
        if cells:
            print(cells)

