        v = c.find(q("v"))
        t = c.get("t")
        raw = v.text if v is not None else None
        if raw is not None and t == "s":
            try:
                idx = int(raw)
                raw = shared[idx] if idx < len(shared) else raw
            except ValueError:
                pass
        cells[col] = raw
    rows.append(cells)

# Expense rows 11-22: category in col A, amount in col C
cat_map = OrderedDict()
for cells in rows:
    cat = cells.get("A")
    amt = cells.get("C")
    if cat and amt is not None:
        try:
            val = float(amt)
        except ValueError:
            continue
        cat_map.setdefault(cat, 0.0)
        cat_map[cat] += val

grand = 0.0
for cat, sub in cat_map.items():
    print("%-15s %8.2f" % (cat, sub))
    grand += sub
print("TOTAL EXPENSES: %.2f" % grand)

